<script setup lang="ts">
import {ref,watch} from 'vue';import {ArrowUpRight,ArrowRight,Activity,CheckCircle2} from 'lucide-vue-next';import {api,type Overview} from '../api';import {usePoll,useMetrics} from '../composables/poll';import {money,time} from '../money';import MetricChart from '../components/MetricChart.vue';import DataState from '../components/DataState.vue';import StatusBadge from '../components/StatusBadge.vue';
const {data,error,loading,updatedAt}=usePoll(s=>api<Overview>('/overview',{signal:s}));const metrics=useMetrics();const samples=ref<{at:string;rate:number|null;queue:number|null;replicas:number|null}[]>([]);
watch(metrics.data,value=>{if(value)samples.value=[...samples.value,{at:value.refreshedAt,rate:finite(value.requestRate?.[0]?.value[1]),queue:value.queue?.ready??null,replicas:value.cluster?.deployments?.find(d=>d.name==='loan-worker')?.status.readyReplicas??null}].slice(-60)});
function finite(s?:string){const n=s===undefined?NaN:Number(s);return Number.isFinite(n)?n:null}
</script>
<template><div class="page-title"><div><p class="eyebrow">OPERATIONS AT A GLANCE</p><h1>Month-end, under control.</h1><p class="muted">Follow payments from bank delivery to a balanced ledger.</p></div><RouterLink to="/simulator" class="action-link">Open bank simulator <ArrowUpRight :size="17"/></RouterLink></div><DataState :loading="loading" :error="error" :updated-at="updatedAt"/>
<div class="hero"><div><span class="hero-kicker"><span class="status-dot"/>FICTIONAL MONTHLY LOAN PRODUCT</span><h2>One payment.<br/>Every satang accounted for.</h2><p>9,000 THB → 1,000 interest + 8,000 principal.<br/>Inspect LOAN-1001 to verify the actual result.</p><RouterLink to="/loans/LOAN-1001">Explore the example loan <ArrowRight :size="16"/></RouterLink></div><div class="hero-flow"><div>BANK WEBHOOK</div><span>↓ durable receipt</span><div><Activity :size="17"/>ASYNC ALLOCATION</div><span>↓ atomic journal</span><div><CheckCircle2 :size="17"/>LOAN LEDGER</div></div><span class="hero-number">01 / 07</span></div>
<div class="stat-grid"><RouterLink to="/loans" class="stat-card"><span>Active loans <ArrowUpRight :size="15"/></span><strong>{{data?.loans?.unavailable?'Unavailable':data?.loans?.activeLoans?.toLocaleString()??'—'}}</strong><small>Seeded fictional customers</small></RouterLink><RouterLink to="/loans" class="stat-card"><span>Actual principal outstanding <ArrowUpRight :size="15"/></span><strong class="money-stat">{{money(data?.loans?.outstandingPrincipal)}}</strong><small>Posted principal repayments reflected</small></RouterLink><RouterLink to="/loans" class="stat-card"><span>Due at business date <ArrowUpRight :size="15"/></span><strong class="money-stat">{{money(data?.loans?.dueAmount)}}</strong><small>Cutoff: 31 Oct 2026 · Bangkok</small></RouterLink><RouterLink to="/payments?status=Applied" class="stat-card"><span>Applied payments today <ArrowUpRight :size="15"/></span><strong>{{data?.loans?.appliedPaymentsToday??'—'}}</strong><small>UTC application day</small></RouterLink><RouterLink to="/payments?status=Pending" class="stat-card"><span>Pending publication <ArrowUpRight :size="15"/></span><strong>{{data?.webhook?.pendingOutbox??'—'}}</strong><small>Oldest: {{time(data?.webhook?.oldestPendingAt)}}</small></RouterLink><RouterLink to="/failures" class="stat-card"><span>Needs review <ArrowUpRight :size="15"/></span><strong class="amber-text">{{data?.loans?.reviewCount??'—'}}</strong><small>Unmatched, credit, timestamp or identity</small></RouterLink></div>
<div class="two-col"><section class="panel"><div class="panel-heading"><div><h3>Workload & backlog</h3><p>Observed samples · aligned time axis · last 3 minutes</p></div><RouterLink to="/scaling">Inspect telemetry ↗</RouterLink></div><MetricChart :samples="samples"/><p class="chart-note">{{metrics.data.value?.autoscaling??'Connecting to telemetry…'}}. Missing series remain unavailable.</p></section><section class="panel"><div class="panel-heading"><h3>Dependency health</h3><span class="eyebrow">LIVE READS</span></div><div v-for="(dep,name) in metrics.data.value?.dependencies" :key="name" class="dependency"><span>{{String(name).toLowerCase()}} service</span><StatusBadge :status="dep.status"/></div><div class="context-box"><span>RUNTIME</span><strong>{{data?.runtimeMode??'Unavailable'}}</strong><small>Durable acceptance precedes eventual allocation.</small></div></section></div>
<section class="panel"><div class="panel-heading"><div><h3>Recent simulator runs</h3><p>Planned unique payments are separate from delivery attempts.</p></div><RouterLink to="/simulator">View all runs ↗</RouterLink></div><el-table :data="Array.isArray(data?.runs)?data.runs.slice(0,5):[]"><el-table-column prop="preset" label="Run preset"/><el-table-column label="Started"><template #default="{row}">{{time(row.createdAt)}}</template></el-table-column><el-table-column prop="plannedUnique" label="Unique transactions"/><el-table-column label="State"><template #default="{row}"><StatusBadge :status="row.status"/></template></el-table-column></el-table><p class="chart-note">Business aggregates are eventually consistent. Backend cutoff: {{time(data?.loans?.cutoff)}}.</p></section>
</template>

